<?php
declare(strict_types=1);
use App\Core\Application;use App\Services\{BackupService,CertificateService,EpgService,MediaStatusService,StreamMonitorService,TaskQueueService,WatchFolderService};
require dirname(__DIR__).'/vendor/autoload.php';$app=Application::boot(dirname(__DIR__));$db=$app->get(\PDO::class);$locked=(int)$db->query("SELECT GET_LOCK('orionx_scheduler',0)")->fetchColumn();if($locked!==1){echo "Scheduler omitido: ya existe otro ciclo activo.\n";exit(0);}$db->exec("INSERT INTO scheduler_runs(status) VALUES('running')");$run=(int)$db->lastInsertId();
try{$db->exec('INSERT IGNORE INTO bouquet_content_items(bouquet_id,content_item_id) SELECT bc.bouquet_id,c.id FROM bouquet_categories bc JOIN content_items c ON c.category_id=bc.category_id');$db->exec('INSERT IGNORE INTO package_content_items(package_id,content_item_id) SELECT pc.package_id,c.id FROM package_categories pc JOIN content_items c ON c.category_id=pc.category_id');$db->exec('INSERT IGNORE INTO package_content_items(package_id,content_item_id) SELECT pb.package_id,bi.content_item_id FROM package_bouquets pb JOIN bouquet_content_items bi ON bi.bouquet_id=pb.bouquet_id JOIN bouquets b ON b.id=pb.bouquet_id AND b.active=1');$queue=$app->get(TaskQueueService::class);$minute=date('YmdHi');$day=date('Ymd');$summary=['watch_folders'=>$app->get(WatchFolderService::class)->dispatchDue(),'epg'=>$app->get(EpgService::class)->queueDue(),'streams'=>$app->get(StreamMonitorService::class)->queueDue(),'media'=>$app->get(MediaStatusService::class)->queueDue(),'certificates'=>$app->get(CertificateService::class)->scheduleRenewals(),'backups'=>$app->get(BackupService::class)->scheduleDue()];$queue->enqueue('sync_balancers',['heartbeat_ttl'=>90],10,'sync-balancers-'.$minute);$queue->enqueue('cleanup_sessions',[],20,'cleanup-sessions-'.$minute);if(date('H:i')==='03:00')$queue->enqueue('rotate_logs',[],200,'rotate-logs-'.$day);$summary['recovered_jobs']=$queue->recoverPending();$db->prepare("UPDATE scheduler_runs SET status='completed',summary=?,completed_at=NOW() WHERE id=?")->execute([json_encode($summary,JSON_THROW_ON_ERROR),$run]);echo 'Scheduler ejecutado: '.json_encode($summary,JSON_UNESCAPED_UNICODE).PHP_EOL;}catch(Throwable $e){$db->prepare("UPDATE scheduler_runs SET status='failed',error_message=?,completed_at=NOW() WHERE id=?")->execute([substr($e->getMessage(),0,65535),$run]);fwrite(STDERR,$e->getMessage().PHP_EOL);exit(1);}finally{$db->query("SELECT RELEASE_LOCK('orionx_scheduler')");}
